import { createServer } from 'node:http';
import { readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = join(__dirname, 'books.json');
const PORT = process.env.PORT || 3000;

/** @typedef {{id:string,title:string,author:string,status:'reading'|'finished',notes:string}} Book */

async function loadBooks() {
  if (!existsSync(DATA_FILE)) return [];
  try {
    const raw = await readFile(DATA_FILE, 'utf8');
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

async function saveBooks(/** @type {Book[]} */ books) {
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2), 'utf8');
}

async function readBody(/** @type {import('node:http').IncomingMessage} */ req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  return Buffer.concat(chunks).toString('utf8');
}

function parseForm(/** @type {string} */ body) {
  const params = new URLSearchParams(body);
  const obj = {};
  for (const [k, v] of params.entries()) obj[k] = v;
  return obj;
}

function escapeHtml(/** @type {string} */ s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function bookCard(/** @type {Book} */ book) {
  const e = (s) => escapeHtml(s);
  return `
    <article class="book">
      <a href="/books/${e(book.id)}">
        <h3>${e(book.title)}</h3>
        <p class="author">${e(book.author)}</p>
      </a>
      ${book.status === 'reading'
        ? `<form method="post" action="/books/${e(book.id)}/finish">
             <button type="submit">Mark as finished</button>
           </form>`
        : `<span class="badge">Finished</span>`}
    </article>`;
}

function renderHome(/** @type {Book[]} */ books) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');
  return page(
    'My Books',
    `
    <section class="add">
      <h2>Add a book</h2>
      <form method="post" action="/books">
        <label>Title <input type="text" name="title" required></label>
        <label>Author <input type="text" name="author" required></label>
        <label>Notes <textarea name="notes" rows="3"></textarea></label>
        <button type="submit">Add</button>
      </form>
    </section>

    <section>
      <h2>Currently reading</h2>
      ${reading.length
        ? `<div class="grid">${reading.map(bookCard).join('')}</div>`
        : `<p class="empty">Nothing in progress yet.</p>`}
    </section>

    <section>
      <h2>Finished</h2>
      ${finished.length
        ? `<div class="grid">${finished.map(bookCard).join('')}</div>`
        : `<p class="empty">No finished books yet.</p>`}
    </section>`
  );
}

function renderBook(/** @type {Book} */ book) {
  const e = (s) => escapeHtml(s);
  return page(
    book.title,
    `
    <article class="detail">
      <p><a href="/">← Back to all books</a></p>
      <h1>${e(book.title)}</h1>
      <p class="author">by ${e(book.author)}</p>
      <p class="status">${book.status === 'reading' ? 'Currently reading' : 'Finished'}</p>
      ${book.status === 'reading'
        ? `<form method="post" action="/books/${e(book.id)}/finish">
             <button type="submit">Mark as finished</button>
           </form>`
        : ''}
      <h2>Notes</h2>
      <div class="notes">${e(book.notes) || '<em>No notes yet.</em>'}</div>
    </article>`
  );
}

function page(/** @type {string} */ title, /** @type {string} */ body) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} — Book Tracker</title>
  <style>
    :root { color-scheme: light dark; }
    * { box-sizing: border-box; }
    body {
      font: 16px/1.5 system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
      max-width: 720px; margin: 2rem auto; padding: 0 1rem;
      color: CanvasText; background: Canvas;
    }
    header { border-bottom: 1px solid GrayText; padding-bottom: 0.5rem; margin-bottom: 1.5rem; }
    header a { color: inherit; text-decoration: none; }
    h1 { font-size: 1.4rem; }
    h2 { margin-top: 2rem; font-size: 1.15rem; }
    form { display: grid; gap: 0.6rem; max-width: 24rem; }
    label { display: grid; gap: 0.2rem; font-weight: 600; }
    input, textarea { font: inherit; padding: 0.35rem 0.5rem; border: 1px solid GrayText; border-radius: 4px; background: inherit; color: inherit; }
    button { padding: 0.4rem 0.9rem; border: 1px solid GrayText; border-radius: 4px; background: Canvas; color: inherit; cursor: pointer; }
    button:hover { background: rgba(127,127,127,0.2); }
    .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 1rem; }
    .book { border: 1px solid GrayText; border-radius: 6px; padding: 0.8rem; }
    .book a { color: inherit; text-decoration: none; }
    .book h3 { margin: 0 0 0.2rem; font-size: 1rem; }
    .author { color: GrayText; margin: 0; font-size: 0.9rem; }
    .badge { font-size: 0.75rem; color: GrayText; }
    .empty { color: GrayText; font-style: italic; }
    .detail .status { color: GrayText; }
    .notes { white-space: pre-wrap; border: 1px solid GrayText; border-radius: 4px; padding: 0.8rem; min-height: 4rem; }
    .add form { margin-top: 0.5rem; }
  </style>
</head>
<body>
  <header><h1><a href="/">Book Tracker</a></h1></header>
  ${body}
</body>
</html>`;
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  try {
    // Home
    if (req.method === 'GET' && url.pathname === '/') {
      const books = await loadBooks();
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(renderHome(books));
      return;
    }

    // Create book
    if (req.method === 'POST' && url.pathname === '/books') {
      const body = parseForm(await readBody(req));
      const title = (body.title || '').trim();
      const author = (body.author || '').trim();
      if (!title || !author) {
        res.writeHead(400, { 'content-type': 'text/plain; charset=utf-8' });
        res.end('Title and author are required.');
        return;
      }
      const books = await loadBooks();
      const book = {
        id: randomUUID(),
        title,
        author,
        status: 'reading',
        notes: (body.notes || '').trim(),
      };
      books.push(book);
      await saveBooks(books);
      res.writeHead(303, { location: '/' });
      res.end();
      return;
    }

    // Mark finished
    const finishMatch = url.pathname.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === finishMatch[1]);
      if (!book) {
        res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
        res.end('Book not found.');
        return;
      }
      book.status = 'finished';
      await saveBooks(books);
      res.writeHead(303, { location: '/' });
      res.end();
      return;
    }

    // Book detail
    const detailMatch = url.pathname.match(/^\/books\/([^/]+)$/);
    if (req.method === 'GET' && detailMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === detailMatch[1]);
      if (!book) {
        res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
        res.end('Book not found.');
        return;
      }
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(renderBook(book));
      return;
    }

    res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
    res.end('Not found.');
  } catch (err) {
    console.error(err);
    res.writeHead(500, { 'content-type': 'text/plain; charset=utf-8' });
    res.end('Server error.');
  }
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

